/* Board pins: configuration from board_pins_generated.h and the few operations the firmware needs.
 *
 * Signal levels follow the schematic (hardware/kicad, generated by tools/gen_kicad_schematic.py):
 *   driver controls (sheet 10): 10k pull-up to +3V3 at the connector side, so an open contact reads
 *       high and a contact closed to ground reads low: every switch input is active low;
 *   HW_PERMIT (ESTOP_CHAIN_SENSE): high only while the safety loop is energised and the external
 *       watchdog is not asserting;
 *   DRV_EN_GATED (OUTPUT_ENABLE_FEEDBACK): MCU_DRV_EN AND HW_PERMIT, read back;
 *   DRV_NFAULT, WDG_RST_N: open-drain, active low. */
#ifndef SEMMC_STM32G4_BOARD_H
#define SEMMC_STM32G4_BOARD_H

#include <stdbool.h>
#include <stdint.h>

#include "board_pins_generated.h"

typedef struct {
    bool brake, cancel, mode_eco, arm, fault_reset, driver_present;
    bool hw_permit;          /* safety loop energised and watchdog not asserting */
    bool drv_en_gated;       /* driver ENABLE as the driver sees it */
    bool drv_nfault;         /* gate driver reports a fault (pin low) */
    bool ext_wdg_reset;      /* external watchdog output asserted (pin low) */
    bool ina_alert;
} board_inputs_t;

/* Every allocated pin to its table mode, except the six TIM1 gate outputs, which are driven low as
 * plain outputs until pwm.c has configured TIM1 (board_pwm_pins_to_timer). */
void board_gpio_init(void);
void board_pwm_pins_to_timer(void);
void board_read_inputs(board_inputs_t *in);

void board_set_drv_enable(bool on);
void board_set_precharge_bypass(bool on);
void board_set_led_status(bool on);
void board_set_led_fault(bool on);
void board_toggle_ext_wdg(void);
bool board_drv_enable_commanded(void);
/* Either TIM1 break input (BKIN: DRV_NFAULT, BKIN2: BRK2_N) is low now. */
bool board_break_inputs_active(void);

/* Registers only, callable from any fault handler: TIM1 main output off, DRV_ENABLE low, precharge
 * bypass open, gate pins forced low as GPIO. */
void board_force_safe(void);

#endif
